import * as THREE from 'three';
import { createScene } from './data/object.js';
import fs from 'fs';

// Create the scene with the globe object
const scene = createScene();

// OBJ file content
let objContent = '# Exported Three.js Globe Object\n';
objContent += '# Converted to Blender Z-up coordinate system\n\n';

// Track vertices and faces
let vertexIndex = 1;
const vertexMap = new Map(); // Maps geometry -> {startIndex, vertexCount}

// Function to apply Blender Z-up rotation (-90 degrees around X-axis)
function applyBlenderRotation(x, y, z) {
  // Rotation matrix for -90 degrees around X-axis:
  // x' = x
  // y' = z
  // z' = -y
  return {
    x: x,
    y: z,
    z: -y
  };
}

// Function to extract and process geometry from a mesh
function processMesh(mesh, meshName) {
  const geometry = mesh.geometry;
  const position = geometry.attributes.position;
  const index = geometry.index;

  // Handle different geometry types
  if (!position) {
    console.warn(`Skipping mesh ${meshName}: no position attribute`);
    return { startIndex: 0, count: 0 };
  }

  // Get world transform matrix
  const worldMatrix = new THREE.Matrix4();
  mesh.updateWorldMatrix(true, false);
  worldMatrix.copy(mesh.matrixWorld);

  // Create temporary vectors for transformation
  const vertex = new THREE.Vector3();
  const normal = new THREE.Vector3();

  // Process each vertex
  const vertices = [];
  const normals = [];

  for (let i = 0; i < position.count; i++) {
    // Get vertex position
    vertex.set(position.getX(i), position.getY(i), position.getZ(i));

    // Apply world transformation
    vertex.applyMatrix4(worldMatrix);

    // Apply Blender Z-up rotation
    const rotatedVertex = applyBlenderRotation(vertex.x, vertex.y, vertex.z);

    vertices.push(rotatedVertex);
    objContent += `v ${rotatedVertex.x.toFixed(6)} ${rotatedVertex.y.toFixed(6)} ${rotatedVertex.z.toFixed(6)}\n`;

    // Handle normals
    if (position.normal) {
      normal.set(position.getX(i), position.getY(i), position.getZ(i));
      // For normals, we apply the rotation differently
      // We need the inverse transpose of the rotation matrix
      // For -90deg X rotation: nx' = nx, ny' = nz, nz' = -ny
      normal.applyMatrix3(new THREE.Matrix3().getNormalMatrix(worldMatrix));
      const rotatedNormal = {
        x: normal.x,
        y: normal.z,
        z: -normal.y
      };
      normals.push(rotatedNormal);
    }
  }

  objContent += '\n';

  // Store vertex range for this mesh
  const meshStartIndex = vertexIndex;
  const vertexCount = vertices.length;

  // Process faces
  if (index) {
    // Indexed geometry
    for (let i = 0; i < index.count; i += 3) {
      const a = index.getX(i) + meshStartIndex;
      const b = index.getX(i + 1) + meshStartIndex;
      const c = index.getX(i + 2) + meshStartIndex;
      objContent += `f ${a} ${b} ${c}\n`;
    }
  } else {
    // Non-indexed geometry
    for (let i = 0; i < position.count; i += 3) {
      const a = vertexIndex + i;
      const b = vertexIndex + i + 1;
      const c = vertexIndex + i + 2;
      objContent += `f ${a} ${b} ${c}\n`;
    }
  }

  objContent += '\n';

  vertexIndex += vertexCount;

  return { startIndex: meshStartIndex, count: vertexCount };
}

// Process InstancedMesh separately
function processInstancedMesh(instancedMesh) {
  const geometry = instancedMesh.geometry;
  const position = geometry.attributes.position;

  if (!position) {
    console.warn(`Skipping instanced mesh ${instancedMesh.name}: no position attribute`);
    return;
  }

  const instanceCount = instancedMesh.count;

  // Process each instance
  for (let instanceId = 0; instanceId < instanceCount; instanceId++) {
    // Get instance transform
    const instanceMatrix = new THREE.Matrix4();
    instancedMesh.getMatrixAt(instanceId, instanceMatrix);

    // Combine with world transform
    const worldMatrix = new THREE.Matrix4();
    instancedMesh.updateWorldMatrix(true, false);
    worldMatrix.copy(instancedMesh.matrixWorld);

    // Create temporary vectors
    const vertex = new THREE.Vector3();

    // Process each vertex of this instance
    for (let i = 0; i < position.count; i++) {
      // Get vertex position
      vertex.set(position.getX(i), position.getY(i), position.getZ(i));

      // Apply instance transform
      vertex.applyMatrix4(instanceMatrix);
      // Apply world transform
      vertex.applyMatrix4(worldMatrix);

      // Apply Blender Z-up rotation
      const rotatedVertex = applyBlenderRotation(vertex.x, vertex.y, vertex.z);

      objContent += `v ${rotatedVertex.x.toFixed(6)} ${rotatedVertex.y.toFixed(6)} ${rotatedVertex.z.toFixed(6)}\n`;
    }

    // Process faces for this instance
    const index = geometry.index;
    if (index) {
      for (let i = 0; i < index.count; i += 3) {
        const a = vertexIndex + index.getX(i);
        const b = vertexIndex + index.getX(i + 1);
        const c = vertexIndex + index.getX(i + 2);
        objContent += `f ${a} ${b} ${c}\n`;
      }
    } else {
      for (let i = 0; i < position.count; i += 3) {
        const a = vertexIndex + i;
        const b = vertexIndex + i + 1;
        const c = vertexIndex + i + 2;
        objContent += `f ${a} ${b} ${c}\n`;
      }
    }

    vertexIndex += position.count;
    objContent += '\n';
  }
}

// Traverse the scene and export all meshes
console.log('Exporting 3D object to OBJ format...');

scene.traverse((object) => {
  if (object.isMesh) {
    const meshName = object.name || object.uuid;
    console.log(`Processing mesh: ${meshName}`);

    if (object.isInstancedMesh) {
      processInstancedMesh(object);
    } else {
      processMesh(object, meshName);
    }
  }
});

// Write to file
const outputPath = '/root/output/object.obj';
fs.writeFileSync(outputPath, objContent);

console.log(`\nExport complete!`);
console.log(`OBJ file saved to: ${outputPath}`);
console.log(`Total vertices: ${vertexIndex - 1}`);

